const supabaseUrl = process.env.EXPO_PUBLIC_SUPABASE_URL ?? '';
const supabaseAnonKey = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY ?? '';
const profileBaseUrl = process.env.EXPO_PUBLIC_PROFILE_BASE_URL ?? 'https://coachpoints.com';
const supabase = createClient(supabaseUrl, supabaseAnonKey, { auth: { storage: AsyncStorage, autoRefreshToken: true, persistSession: true, detectSessionInUrl: false } });

Notifications.setNotificationHandler({
  handleNotification: async () => ({
    shouldPlaySound: true,
    shouldSetBadge: true,
    shouldShowBanner: true,
    shouldShowList: true,
  }),
});

async function registerForPushNotificationsAsync(userId: string) {
  if (Platform.OS === 'web' || !Device.isDevice) return null;
  if (Platform.OS === 'android') await Notifications.setNotificationChannelAsync('default', { name: 'default', importance: Notifications.AndroidImportance.MAX, vibrationPattern: [0, 250, 250, 250], lightColor: '#2588d8' });
  const permissions = await Notifications.getPermissionsAsync();
  let finalStatus = permissions.status;
  if (finalStatus !== 'granted') finalStatus = (await Notifications.requestPermissionsAsync()).status;
  if (finalStatus !== 'granted') return null;
  const projectId = Constants.expoConfig?.extra?.eas?.projectId ?? Constants.easConfig?.projectId;
  if (!projectId) { console.warn('Push notifications need an EAS projectId in app config.'); return null; }
  const token = (await Notifications.getExpoPushTokenAsync({ projectId })).data;
  await AsyncStorage.setItem(`coachpoints:push-token:${userId}`, token);
  const { error } = await supabase.from('push_tokens').upsert({ user_id: userId, expo_push_token: token, platform: Platform.OS, updated_at: new Date().toISOString() }, { onConflict: 'user_id,expo_push_token' });
  if (error) console.warn('Push token could not be synced:', error.message);
  console.log('Expo push token:', token);
  return token;
}

type Profile = { id: string; account_type: 'athlete' | 'coach'; username: string | null; first_name: string | null; last_name: string | null; avatar_url: string | null; sport: string | null; position: string | null; graduating_class?: string | null; high_school?: string | null; college_university?: string | null; gpa?: string | null; bio: string | null; height?: string | null; weight?: string | null; hudl_highlight_url?: string | null; stats?: Record<string, string> | null; measurables?: Record<string, string> | null };
type Contact = { phone_number: string | null; contact_email: string | null };
type Message = { id: string; sender_id: string; recipient_id: string; body: string; created_at: string; read_at: string | null };
type MessagePerson = { id: string; username: string | null; first_name: string | null; last_name: string | null; avatar_url: string | null };
type CoachList = { id: string; name: string; created_at: string };
type ListMember = { list_id: string; athlete_id: string };
type ListAthlete = { id: string; username: string | null; first_name: string | null; last_name: string | null; sport: string | null; position: string | null; avatar_url: string | null };
type DiscoverPerson = { id: string; account_type: 'athlete' | 'coach'; username: string | null; first_name: string | null; last_name: string | null; sport: string | null; position: string | null; high_school: string | null; college_university: string | null; avatar_url: string | null; bio: string | null };
type FriendConnection = { id: string; requester_id: string; recipient_id: string; status: 'pending' | 'accepted'; created_at?: string; accepted_at?: string | null };

function Diamond({ size = 18, style, green = false }: { size?: number; style?: object; green?: boolean }) {
  return <Image source={green ? require('./assets/coachpoints-mark-green.png') : require('./assets/coachpoints-mark.png')} style={[{ width: size, height: size }, style]} resizeMode="contain" />;
}

export default function App() {
  const [session, setSession] = useState<Session | null>(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => { supabase.auth.getSession().then(({ data }) => { setSession(data.session); setLoading(false); }); const { data: listener } = supabase.auth.onAuthStateChange((_event, next) => setSession(next)); return () => listener.subscription.unsubscribe(); }, []);
  useEffect(() => { if (session) void registerForPushNotificationsAsync(session.user.id).catch((error) => console.warn('Push notification registration failed:', error)); }, [session?.user.id]);
  if (loading) return <Splash />;
  return <SafeAreaProvider>{session ? <PASSport session={session} /> : <Login />}</SafeAreaProvider>;
}

function Splash() { return <View style={styles.splash}><StatusBar style="light" /><Image source={require('./assets/coachpoints-logo.png')} style={styles.splashLogo} resizeMode="contain" /><Text style={styles.splashSub}>Your athletic identity, ready to share.</Text></View>; }

function Login() {
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const signIn = async () => { setBusy(true); setError(''); const { error: authError } = await supabase.auth.signInWithPassword({ email: email.trim(), password }); if (authError) setError(authError.message); setBusy(false); };
  return <SafeAreaView style={styles.loginSafe}><StatusBar style="light" /><LinearGradient colors={['#06152c', '#0b2c58', '#123f78']} style={StyleSheet.absoluteFill} /><ScrollView contentContainerStyle={styles.loginContent} keyboardShouldPersistTaps="handled" keyboardDismissMode="on-drag"><View style={styles.brandMark}><Image source={require('./assets/coachpoints-logo.png')} style={styles.loginLogo} resizeMode="contain" /></View><Text style={styles.loginEyebrow}>YOUR DIGITAL PASSport</Text><Text style={styles.loginTitle}>Bring your game{`\n`}with you.</Text><Text style={styles.loginBody}>Sign in to present your profile, performance, and story in one polished place.</Text><View style={styles.loginCard}><Text style={styles.cardTitle}>Welcome back</Text><Text style={styles.fieldLabel}>Email address</Text><TextInput autoCapitalize="none" autoComplete="email" keyboardType="email-address" placeholder="you@example.com" placeholderTextColor="#8d9aad" style={styles.input} value={email} onChangeText={setEmail} returnKeyType="next" /><Text style={styles.fieldLabel}>Password</Text><TextInput secureTextEntry placeholder="Enter your password" placeholderTextColor="#8d9aad" style={styles.input} value={password} onChangeText={setPassword} returnKeyType="go" onSubmitEditing={signIn} /><Pressable style={({ pressed }) => [styles.primaryButton, pressed && styles.pressed, busy && styles.disabled]} onPress={signIn} disabled={busy}><Text style={styles.primaryButtonText}>{busy ? 'Signing inâ€¦' : 'Enter PASSport'}</Text><ChevronRight color="#071321" size={19} /></Pressable>{error ? <Text style={styles.error}>{error}</Text> : null}</View><Text style={styles.loginFoot}>Secure sign-in powered by CoachPoints</Text></ScrollView></SafeAreaView>;
}

function PASSport({ session }: { session: Session }) {
  const [profile, setProfile] = useState<Profile | null>(null); const [contact, setContact] = useState<Contact | null>(null); const [refreshing, setRefreshing] = useState(false); const [qrLarge, setQrLarge] = useState(false); const [showMessages, setShowMessages] = useState(false); const [messageTargetId, setMessageTargetId] = useState<string | null>(null); const [showLists, setShowLists] = useState(false); const [showDiscover, setShowDiscover] = useState(false); const [showConnections, setShowConnections] = useState(false); const [error, setError] = useState('');
  const load = async () => { setError(''); const [athlete, coach, contacts] = await Promise.all([supabase.from('profiles').select('*').eq('id', session.user.id).maybeSingle(), supabase.from('coachprofiles').select('*').eq('id', session.user.id).maybeSingle(), supabase.from('profile_contacts').select('phone_number, contact_email').eq('user_id', session.user.id).maybeSingle()]); const row = athlete.data ?? coach.data; if (!row) setError(athlete.error?.message ?? coach.error?.message ?? 'We could not load your profile.'); else setProfile({ ...row, account_type: athlete.data ? 'athlete' : 'coach' }); setContact(contacts.data); };
  useEffect(() => { void load(); }, [session.user.id]);
  const signOut = () => Alert.alert('Sign out?', 'You can sign back in anytime.', [{ text: 'Cancel', style: 'cancel' }, { text: 'Sign out', style: 'destructive', onPress: () => supabase.auth.signOut() }]);
  if (error) return <SafeAreaView style={styles.safe}><EmptyState message={error} onRetry={load} /></SafeAreaView>;
  if (!profile) return <Splash />;
  const name = [profile.first_name, profile.last_name].filter(Boolean).join(' ') || 'Your Profile'; const handle = profile.username ? `@${profile.username}` : 'Complete your username'; const isAthlete = profile.account_type === 'athlete'; const publicUrl = `${profileBaseUrl}/${profile.username ?? profile.id}`;
  const accent = isAthlete ? '#2588d8' : '#167a5a'; const accentSoft = isAthlete ? '#e8f3fc' : '#e8f8f1';
  if (showMessages) return <Messages userId={session.user.id} accent={accent} initialTargetId={messageTargetId ?? undefined} onBack={() => { setMessageTargetId(null); setShowMessages(false); }} />; if (showDiscover) return <Discover userId={session.user.id} accent={accent} onBack={() => setShowDiscover(false)} onMessage={(targetId) => { setMessageTargetId(targetId); setShowDiscover(false); setShowMessages(true); }} />; if (showConnections) return <Connections userId={session.user.id} accent={accent} onBack={() => setShowConnections(false)} />;
  if (showLists && !isAthlete) return <CoachLists userId={session.user.id} accent={accent} onBack={() => setShowLists(false)} />;
  return <SafeAreaView style={styles.safe}><StatusBar style="dark" /><ScrollView showsVerticalScrollIndicator={false} refreshControl={<RefreshControl refreshing={refreshing} onRefresh={async () => { setRefreshing(true); await load(); setRefreshing(false); }} tintColor={accent} />}><View style={styles.topbar}><View style={styles.profileBrand}><Image source={isAthlete ? require('./assets/coachpoints-logo.png') : require('./assets/coachpoints-logo-green.png')} style={[styles.profileLogo, { height: isAthlete ? 29 : 43 }]} resizeMode="contain" /></View><View style={styles.topbarActions}><Pressable onPress={() => setShowDiscover(true)} style={styles.iconButton}><Compass color={accent} size={18} /></Pressable>{!isAthlete && <Pressable onPress={() => setShowLists(true)} style={styles.iconButton}><ListChecks color={accent} size={18} /></Pressable>}<Pressable onPress={() => setShowMessages(true)} style={styles.iconButton}><MessageCircle color={accent} size={18} /></Pressable><Pressable onPress={signOut} style={styles.iconButton}><LogOut color="#526174" size={18} /></Pressable></View></View><View style={[styles.hero, isAthlete ? styles.heroAthlete : styles.heroCoach]}><Pressable onPress={() => setShowConnections(true)} style={[styles.heroConnectionsButton, { backgroundColor: accent + '24', borderColor: accent + '66' }]}><UsersRound color={accent} size={15} /><Text style={[styles.heroConnectionsText, { color: accent }]}>Friends</Text></Pressable><View style={[styles.heroGlow, { backgroundColor: isAthlete ? '#1764a4' : '#176a50' }]} /><View style={[styles.avatar, { borderColor: accent }]}>{profile.avatar_url ? <Image source={{ uri: profile.avatar_url }} style={styles.avatarImage} /> : <UserRound color={isAthlete ? '#9cdcff' : '#a3f1d0'} size={31} />}</View><Text style={styles.name}>{name}</Text><Text style={styles.handle}>{handle}</Text><View style={[styles.pill, { backgroundColor: isAthlete ? '#143b60' : '#16382f' }]}><ShieldCheck color={isAthlete ? '#9cddff' : '#79e3b6'} size={14} /><Text style={[styles.pillText, { color: isAthlete ? '#a9e0ff' : '#9be9c7' }]}>CoachPoints member</Text></View></View><View style={styles.qrCard}><View style={styles.qrHeader}><View><Text style={[styles.qrEyebrow, { color: accent }]}>SCAN TO VIEW</Text><Text style={styles.qrTitle}>My profile</Text></View><View style={[styles.qrBadge, { backgroundColor: accentSoft }]}><Diamond green={!isAthlete} color={accent} size={16} /></View></View><View style={[styles.qrFrame, qrLarge && styles.qrFrameLarge, { borderColor: accentSoft }]}><QRCode value={publicUrl} size={qrLarge ? 280 : 190} color={isAthlete ? '#145a94' : '#08111f'} backgroundColor="#ffffff" quietZone={8} /><View style={[styles.qrCenter, { backgroundColor: '#ffffff', top: qrLarge ? 139 : 94 }]}><Diamond green={!isAthlete} color={accent} size={13} /></View></View><Text style={styles.qrHint}>Point a camera here to open {name.split(' ')[0]}'s profile</Text><View style={styles.qrActions}><Pressable onPress={() => setQrLarge((value) => !value)} style={[styles.enlargeButton, { borderColor: accent }]}><Diamond green={!isAthlete} color={accent} size={15} /><Text style={[styles.enlargeText, { color: accent }]}>{qrLarge ? 'Reduce QR' : 'Enlarge QR'}</Text></Pressable><Pressable onPress={() => { Clipboard.setStringAsync(publicUrl); Alert.alert('Link copied', 'Your CoachPoints profile link is ready to share.'); }} style={styles.copyButton}><Copy color={accent} size={16} /><Text style={[styles.copyText, { color: accent }]}>Copy link</Text></Pressable></View></View><View style={styles.content}><View style={styles.sectionHeading}><Text style={styles.sectionTitle}>Profile details</Text><Pressable onPress={() => Alert.alert('Edit profile', 'Profile editing will be available here soon.')}><Pencil color={accent} size={18} /></Pressable></View><Text style={styles.bio}>{profile.bio || 'Add a short bio to tell coaches and teammates what makes your game yours.'}</Text><View style={styles.detailGrid}>{isAthlete ? <><Detail accent={accent} icon={<Award color={accent} size={18} />} label="SPORT" value={profile.sport} /><Detail accent={accent} icon={<MapPin color={accent} size={18} />} label="POSITION" value={profile.position} /><Detail accent={accent} icon={<GraduationCap color={accent} size={18} />} label="CLASS OF" value={profile.graduating_class} /><Detail accent={accent} icon={<BookOpen color={accent} size={18} />} label="SCHOOL" value={profile.high_school} /><Detail accent={accent} icon={<Check color={accent} size={18} />} label="GPA" value={profile.gpa} /><Detail accent={accent} icon={<Sparkles color={accent} size={18} />} label="MEASURABLES" value={formatObject(profile.measurables)} /></> : <><Detail accent={accent} icon={<Award color={accent} size={18} />} label="PROGRAM" value={profile.college_university} /><Detail accent={accent} icon={<MapPin color={accent} size={18} />} label="SPORT" value={profile.sport} /><Detail accent={accent} icon={<UserRound color={accent} size={18} />} label="ROLE" value={profile.position} /></>}</View><View style={[styles.contactCard, { backgroundColor: `${accent}14` } ]}><Text style={[styles.contactTitle, { color: accent }]}>Connect with me</Text>{contact?.contact_email ? <ContactLine icon={<Mail color={accent} size={16} />} text={contact.contact_email} /> : null}{contact?.phone_number ? <ContactLine icon={<Phone color={accent} size={16} />} text={contact.phone_number} /> : null}{!contact?.contact_email && !contact?.phone_number ? <Text style={styles.muted}>No contact details shared yet.</Text> : null}</View><View style={styles.lastUpdated}><ExternalLink color="#8a98a8" size={14} /><Text style={styles.muted}>Public profile: {publicUrl.replace('https://', '')}</Text></View></View></ScrollView></SafeAreaView>;
}

async function loadConnection(userId: string, targetId: string) { return supabase.from('friend_connections').select('id, requester_id, recipient_id, status').or('and(requester_id.eq.' + userId + ',recipient_id.eq.' + targetId + '),and(requester_id.eq.' + targetId + ',recipient_id.eq.' + userId + ')').maybeSingle(); }

function ConnectionButton({ userId, targetId, targetName, accent, onMessage }: { userId: string; targetId: string; targetName: string; accent: string; onMessage?: (targetId: string) => void }) {
  const [connection, setConnection] = useState<FriendConnection | null>(null); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  const refresh = async () => { setLoading(true); const { data, error: loadError } = await loadConnection(userId, targetId); setConnection((data as FriendConnection | null) ?? null); setError(loadError ? 'Unavailable' : ''); setLoading(false); };
  useEffect(() => { void refresh(); }, [userId, targetId]);
  const incoming = connection?.status === 'pending' && connection.recipient_id === userId; const outgoing = connection?.status === 'pending' && connection.requester_id === userId; const friend = connection?.status === 'accepted';
  const update = async () => { if (loading || saving || error) return; setSaving(true); setError(''); let mutationError: { message: string } | null = null; if (!connection) ({ error: mutationError } = await supabase.rpc('send_friend_request', { target_user_id: targetId })); else if (incoming) ({ error: mutationError } = await supabase.rpc('accept_friend_request', { connection_id: connection.id })); else { const action = friend ? 'Remove ' + targetName + ' from your friends?' : 'Cancel your request to ' + targetName + '?'; Alert.alert(action, undefined, [{ text: 'Cancel', style: 'cancel' }, { text: 'Confirm', style: 'destructive', onPress: async () => { const result = await supabase.rpc('delete_friend_connection', { connection_id: connection.id, expected_status: connection.status }); if (result.error) setError(result.error.message); else await refresh(); setSaving(false); } }]); return; } if (mutationError) setError(mutationError.message); else await refresh(); setSaving(false); };
  const label = saving || loading ? 'â€¦' : incoming ? 'Accept' : outgoing ? 'Requested' : friend ? 'Friends' : 'Follow';
  return <View style={styles.connectionActions}><Pressable onPress={update} disabled={loading || saving || Boolean(error)} style={[styles.connectionButton, { borderColor: accent, backgroundColor: friend ? accent + '14' : accent }]}><>{friend ? <Check color={accent} size={14} /> : <UserPlus color="#fff" size={14} />}</><Text style={[styles.connectionButtonText, friend && { color: accent }]}>{label}</Text></Pressable>{friend && onMessage ? <Pressable onPress={() => onMessage(targetId)} style={[styles.discoverMessageButton, { backgroundColor: accent }]}><MessageCircle color="#fff" size={16} /></Pressable> : null}</View>;
}

function Connections({ userId, accent, onBack }: { userId: string; accent: string; onBack: () => void }) {
  const [connections, setConnections] = useState<FriendConnection[]>([]); const [people, setPeople] = useState<DiscoverPerson[]>([]); const [tab, setTab] = useState<'friends' | 'requests'>('friends'); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const load = async () => { setLoading(true); setError(''); const { data, error: connectionError } = await supabase.from('friend_connections').select('id, requester_id, recipient_id, status, created_at, accepted_at').or('requester_id.eq.' + userId + ',recipient_id.eq.' + userId).order('created_at', { ascending: false }); const rows = (data ?? []) as FriendConnection[]; const ids = Array.from(new Set(rows.flatMap((row) => [row.requester_id, row.recipient_id]).filter((id) => id !== userId))); let athleteRows: DiscoverPerson[] = []; let coachRows: DiscoverPerson[] = []; if (ids.length) { const [athletes, coaches] = await Promise.all([supabase.from('profiles').select('*').in('id', ids), supabase.from('coachprofiles').select('*').in('id', ids)]); athleteRows = (athletes.data ?? []).map((person) => ({ ...(person as DiscoverPerson), account_type: 'athlete' })); coachRows = (coaches.data ?? []).map((person) => ({ ...(person as DiscoverPerson), account_type: 'coach' })); } setConnections(rows); setPeople(Array.from(new Map([...athleteRows, ...coachRows].map((person) => [person.id, person])).values())); if (connectionError) setError(connectionError.message); setLoading(false); };
  useEffect(() => { void load(); }, [userId]);
  const personFor = (row: FriendConnection) => people.find((person) => person.id === (row.requester_id === userId ? row.recipient_id : row.requester_id)); const personName = (person?: DiscoverPerson) => person ? [person.first_name, person.last_name].filter(Boolean).join(' ') || person.username || 'CoachPoints member' : 'CoachPoints member'; const friends = connections.filter((row) => row.status === 'accepted'); const requests = connections.filter((row) => row.status === 'pending');
  const rows = tab === 'friends' ? friends : requests;
  return <SafeAreaView style={styles.safe}><StatusBar style="dark" /><View style={styles.connectionsHeader}><Pressable onPress={onBack} style={[styles.backButton, { backgroundColor: accent + '14' }]}><ArrowLeft color={accent} size={20} /></Pressable><View style={styles.messageTopTitle}><Text style={[styles.topbarKicker, { color: accent }]}>COACHPOINTS</Text><Text style={styles.topbarTitle}>Connections</Text></View><UsersRound color={accent} size={23} /></View><ScrollView contentContainerStyle={styles.connectionsContent} refreshControl={<RefreshControl refreshing={loading} onRefresh={load} tintColor={accent} />}><View style={[styles.connectionsHero, { backgroundColor: accent }]}><Text style={styles.discoverIntroKicker}>YOUR NETWORK</Text><Text style={styles.discoverIntroTitle}>Build your circle.</Text><Text style={styles.discoverIntroBody}>Connect with athletes and coaches to unlock mutual messaging.</Text></View><View style={styles.connectionTabs}><Pressable onPress={() => setTab('friends')} style={[styles.connectionTab, tab === 'friends' && { backgroundColor: accent }]}><Text style={[styles.connectionTabText, tab === 'friends' && styles.listTabTextActive]}>Friends ({friends.length})</Text></Pressable><Pressable onPress={() => setTab('requests')} style={[styles.connectionTab, tab === 'requests' && { backgroundColor: accent }]}><Text style={[styles.connectionTabText, tab === 'requests' && styles.listTabTextActive]}>Requests ({requests.length})</Text></Pressable></View>{error ? <Text style={styles.messageError}>{error}</Text> : null}{!loading && !rows.length ? <View style={styles.messageEmpty}><UsersRound color={accent} size={32} /><Text style={styles.messageEmptyTitle}>{tab === 'friends' ? 'No friends yet' : 'No pending requests'}</Text><Text style={styles.muted}>Discover athletes and coaches to grow your network.</Text></View> : rows.map((row) => { const person = personFor(row); return <View key={row.id} style={styles.connectionRow}><View style={[styles.discoverAvatar, { backgroundColor: accent + '14' }]}>{person?.avatar_url ? <Image source={{ uri: person.avatar_url }} style={styles.personAvatarImage} /> : <Text style={[styles.personInitial, { color: accent }]}>{personName(person).charAt(0).toUpperCase()}</Text>}</View><View style={styles.discoverCopy}><Text style={styles.discoverName}>{personName(person)}</Text><Text style={[styles.discoverRole, { color: accent }]}>{person?.account_type === 'coach' ? 'Coach' : 'Athlete'}{person?.sport ? ' Â· ' + person.sport : ''}</Text><Text style={styles.discoverMeta}>{person?.position || person?.high_school || person?.college_university || (row.status === 'pending' ? 'Pending request' : 'CoachPoints connection')}</Text></View>{person && <ConnectionButton userId={userId} targetId={person.id} targetName={personName(person)} accent={accent} />}</View>; })}</ScrollView></SafeAreaView>;
}

function PublicProfile({ person, userId, accent, onBack, onMessage }: { person: DiscoverPerson; userId: string; accent: string; onBack: () => void; onMessage: () => void }) {
  const displayName = [person.first_name, person.last_name].filter(Boolean).join(' ') || person.username || 'CoachPoints member';
  const profileUrl = `${profileBaseUrl}/${person.username ?? person.id}`;
  const isCoach = person.account_type === 'coach';
  return <SafeAreaView style={styles.safe}><StatusBar style="dark" /><View style={styles.publicProfileHeader}><Pressable onPress={onBack} style={[styles.backButton, { backgroundColor: accent + '14' }]}><ArrowLeft color={accent} size={20} /></Pressable><Text style={[styles.topbarTitle, { color: accent }]}>Profile</Text><View style={{ width: 40 }} /></View><ScrollView contentContainerStyle={styles.publicProfileContent}><View style={[styles.publicProfileHero, { backgroundColor: isCoach ? '#0b1727' : '#092d52' }]}><View style={[styles.publicProfileAvatar, { borderColor: accent }]}>{person.avatar_url ? <Image source={{ uri: person.avatar_url }} style={styles.avatarImage} /> : <UserRound color={accent} size={34} />}</View><Text style={styles.publicProfileName}>{displayName}</Text><Text style={styles.publicProfileHandle}>{person.username ? `@${person.username}` : 'CoachPoints member'}</Text><Text style={[styles.publicProfileRole, { color: accent }]}>{isCoach ? 'Coach' : 'Athlete'}{person.sport ? ` Â· ${person.sport}` : ''}</Text></View><View style={styles.publicProfileActions}><ConnectionButton userId={userId} targetId={person.id} targetName={displayName} accent={accent} onMessage={() => onMessage()} /></View><View style={styles.publicProfileQr}><Text style={[styles.qrEyebrow, { color: accent }]}>SCAN TO VIEW</Text><QRCode value={profileUrl} size={190} color={isCoach ? '#08111f' : '#145a94'} backgroundColor="#ffffff" quietZone={8} /><Text style={styles.qrHint}>Scan to open {displayName}'s profile</Text></View><View style={styles.publicProfileInfo}>{person.bio ? <><Text style={styles.publicProfileSectionTitle}>About</Text><Text style={styles.bio}>{person.bio}</Text></> : null}<Text style={styles.publicProfileSectionTitle}>Profile details</Text><Detail accent={accent} icon={<Award color={accent} size={18} />} label="SPORT" value={person.sport} />{person.position ? <Detail accent={accent} icon={<MapPin color={accent} size={18} />} label={isCoach ? 'ROLE' : 'POSITION'} value={person.position} /> : null}{person.high_school ? <Detail accent={accent} icon={<BookOpen color={accent} size={18} />} label="SCHOOL" value={person.high_school} /> : null}{person.college_university ? <Detail accent={accent} icon={<GraduationCap color={accent} size={18} />} label="COLLEGE / UNIVERSITY" value={person.college_university} /> : null}</View></ScrollView></SafeAreaView>;
}

function Discover({ userId, accent, onBack, onMessage }: { userId: string; accent: string; onBack: () => void; onMessage: (targetId: string) => void }) {
  const [people, setPeople] = useState<DiscoverPerson[]>([]); const [selectedPerson, setSelectedPerson] = useState<DiscoverPerson | null>(null); const [query, setQuery] = useState(''); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const load = async () => { setLoading(true); setError(''); const [athletes, coaches] = await Promise.all([supabase.from('profiles').select('*').neq('id', userId).limit(100), supabase.from('coachprofiles').select('*').neq('id', userId).limit(100)]); const errors = [athletes.error, coaches.error].filter(Boolean); if (errors.length && !(athletes.data?.length || coaches.data?.length)) setError(errors.map((item) => item?.message).join(' Â· ') || 'We could not load Discover right now.'); const combined = [...((athletes.data ?? []) as DiscoverPerson[]).map((person) => ({ ...person, account_type: 'athlete' as const })), ...((coaches.data ?? []) as DiscoverPerson[]).map((person) => ({ ...person, account_type: 'coach' as const }))]; const unique = Array.from(new Map(combined.map((person) => [person.id, person])).values()); setPeople(unique); setLoading(false); };
  useEffect(() => { void load(); }, [userId]);
  const visible = people.filter((person) => { const haystack = [person.first_name, person.last_name, person.username, person.sport, person.position, person.high_school, person.college_university].filter(Boolean).join(' ').toLowerCase(); return haystack.includes(query.trim().toLowerCase()); });
  const personName = (person: DiscoverPerson) => [person.first_name, person.last_name].filter(Boolean).join(' ') || person.username || 'CoachPoints member';
  if (selectedPerson) return <PublicProfile person={selectedPerson} accent={accent} onBack={() => setSelectedPerson(null)} onMessage={() => onMessage(selectedPerson.id)} userId={userId} />;
  return <SafeAreaView style={styles.safe}><StatusBar style="dark" /><View style={styles.discoverHeader}><Pressable onPress={onBack} style={[styles.backButton, { backgroundColor: accent + '14' }]}><ArrowLeft color={accent} size={20} /></Pressable><View style={styles.messageTopTitle}><Text style={[styles.topbarKicker, { color: accent }]}>COACHPOINTS</Text><Text style={styles.topbarTitle}>Discover</Text></View><Compass color={accent} size={23} /></View><ScrollView contentContainerStyle={styles.discoverContent} refreshControl={<RefreshControl refreshing={loading} onRefresh={load} tintColor={accent} />}><View style={[styles.discoverIntro, { backgroundColor: accent }]}><Text style={styles.discoverIntroKicker}>FIND YOUR NEXT CONNECTION</Text><Text style={styles.discoverIntroTitle}>Explore the CoachPoints community.</Text><Text style={styles.discoverIntroBody}>Browse athletes and coaches, then open a conversation when you find the right fit.</Text></View><View style={styles.discoverSearch}><Search color="#7d8b9a" size={18} /><TextInput value={query} onChangeText={setQuery} placeholder="Search by name, sport, or school" placeholderTextColor="#8a98a8" style={styles.discoverSearchInput} /></View>{error ? <Text style={styles.messageError}>{error}</Text> : null}{!loading && !visible.length ? <View style={styles.messageEmpty}><Compass color={accent} size={32} /><Text style={styles.messageEmptyTitle}>{query ? 'No matches found' : 'No profiles to discover'}</Text><Text style={styles.muted}>{query ? 'Try a different name, sport, or school.' : 'New community profiles will appear here.'}</Text></View> : visible.map((person) => <Pressable key={person.id} onPress={() => setSelectedPerson(person)} style={styles.discoverCard}><View style={[styles.discoverAvatar, { backgroundColor: accent + '14' }]}>{person.avatar_url ? <Image source={{ uri: person.avatar_url }} style={styles.personAvatarImage} /> : <Text style={[styles.personInitial, { color: accent }]}>{personName(person).charAt(0).toUpperCase()}</Text>}</View><View style={styles.discoverCopy}><Text style={styles.discoverName}>{personName(person)}</Text><Text style={[styles.discoverRole, { color: accent }]}>{person.account_type === 'coach' ? 'Coach' : 'Athlete'}{person.sport ? ' Â· ' + person.sport : ''}</Text><Text style={styles.discoverMeta}>{person.position || person.high_school || person.college_university || 'CoachPoints member'}</Text>{person.bio ? <Text numberOfLines={2} style={styles.discoverBio}>{person.bio}</Text> : null}</View><ConnectionButton userId={userId} targetId={person.id} targetName={personName(person)} accent={accent} onMessage={onMessage} /></Pressable>)}</ScrollView></SafeAreaView>;
}

function CoachLists({ userId, accent, onBack }: { userId: string; accent: string; onBack: () => void }) {
  const [lists, setLists] = useState<CoachList[]>([]); const [members, setMembers] = useState<ListMember[]>([]); const [athletes, setAthletes] = useState<ListAthlete[]>([]); const [selectedId, setSelectedId] = useState(''); const [newName, setNewName] = useState(''); const [message, setMessage] = useState(''); const [showAdd, setShowAdd] = useState(false); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState('');
  const selected = lists.find((list) => list.id === selectedId) ?? null; const memberIds = new Set(members.filter((member) => member.list_id === selectedId).map((member) => member.athlete_id)); const selectedAthletes = athletes.filter((athlete) => memberIds.has(athlete.id));
  const load = async () => { setLoading(true); setError(''); const [{ data: listData, error: listError }, { data: memberData, error: memberError }, { data: athleteData, error: athleteError }] = await Promise.all([supabase.from('coach_lists').select('id, name, created_at').order('created_at', { ascending: true }), supabase.from('coach_list_members').select('list_id, athlete_id'), supabase.from('public_profile_cards').select('id, username, first_name, last_name, sport, position, avatar_url').order('last_name', { ascending: true })]); if (listError || memberError || athleteError) setError((listError ?? memberError ?? athleteError)?.message ?? 'Unable to load recruiting lists.'); const nextLists = (listData ?? []) as CoachList[]; setLists(nextLists); setMembers((memberData ?? []) as ListMember[]); setAthletes((athleteData ?? []) as ListAthlete[]); if (!selectedId && nextLists[0]) setSelectedId(nextLists[0].id); setLoading(false); };
  useEffect(() => { void load(); }, [userId]);
  const createList = async () => { const name = newName.trim(); if (!name || saving) return; setSaving(true); const { data, error: createError } = await supabase.from('coach_lists').insert({ coach_id: userId, name }).select('id, name, created_at').single(); if (createError) setError(createError.message); else { setLists((current) => [...current, data as CoachList]); setSelectedId((data as CoachList).id); setNewName(''); } setSaving(false); };
  const toggleAthlete = async (athlete: ListAthlete) => { if (!selected || saving) return; setSaving(true); const existing = memberIds.has(athlete.id); const result = existing ? await supabase.from('coach_list_members').delete().eq('list_id', selected.id).eq('athlete_id', athlete.id) : await supabase.from('coach_list_members').insert({ list_id: selected.id, athlete_id: athlete.id }); if (result.error) setError(result.error.message); else setMembers((current) => existing ? current.filter((member) => !(member.list_id === selected.id && member.athlete_id === athlete.id)) : [...current, { list_id: selected.id, athlete_id: athlete.id }]); setSaving(false); };
  const deleteList = () => { if (!selected) return; Alert.alert('Delete list?', `Remove â€œ${selected.name}â€ and its memberships?`, [{ text: 'Cancel', style: 'cancel' }, { text: 'Delete', style: 'destructive', onPress: async () => { const { error: deleteError } = await supabase.from('coach_lists').delete().eq('id', selected.id); if (deleteError) setError(deleteError.message); else { const next = lists.filter((list) => list.id !== selected.id); setLists(next); setSelectedId(next[0]?.id ?? ''); setMembers((current) => current.filter((member) => member.list_id !== selected.id)); } } }]); };
  const messageEveryone = async () => { if (!selected || !message.trim() || saving) return; setSaving(true); setError(''); const { data: eligibility, error: eligibilityError } = await supabase.rpc('get_coach_list_message_eligibility', { target_list_id: selected.id }).single(); if (eligibilityError) setError(eligibilityError.message); else if (!eligibility?.can_message) setError(`Only mutual connections can receive a list message (${eligibility?.connected_athletes ?? 0} of ${eligibility?.total_athletes ?? 0} eligible).`); else { const { error: sendError } = await supabase.rpc('send_coach_list_message', { target_list_id: selected.id, message_body: message.trim() }); if (sendError) setError(sendError.message); else { Alert.alert('Message sent', `Your message was sent individually to everyone in ${selected.name}.`); setMessage(''); } } setSaving(false); };
  return <SafeAreaView style={styles.safe}><StatusBar style="dark" /><View style={styles.listHeader}><Pressable onPress={onBack} style={styles.backButton}><ArrowLeft color={accent} size={20} /></Pressable><View style={styles.messageTopTitle}><Text style={[styles.topbarKicker, { color: accent }]}>COACHPOINTS</Text><Text style={styles.topbarTitle}>Recruiting lists</Text></View><ListChecks color={accent} size={22} /></View><ScrollView contentContainerStyle={styles.listContent} refreshControl={<RefreshControl refreshing={loading} onRefresh={load} tintColor={accent} />}><View style={styles.listIntro}><Text style={styles.listIntroTitle}>Organize your prospects</Text><Text style={styles.muted}>Keep private lists of athletes and message an entire eligible list at once.</Text></View><View style={styles.createListRow}><TextInput value={newName} onChangeText={setNewName} placeholder="New list name" placeholderTextColor="#8a98a8" style={styles.listInput} maxLength={80} /><Pressable onPress={createList} disabled={!newName.trim() || saving} style={[styles.addListButton, { backgroundColor: accent }, (!newName.trim() || saving) && styles.disabled]}><Text style={styles.addListText}>Add</Text></Pressable></View>{error ? <Text style={styles.messageError}>{error}</Text> : null}{!loading && !lists.length ? <View style={styles.messageEmpty}><ListChecks color="#9bb5cc" size={32} /><Text style={styles.messageEmptyTitle}>No lists yet</Text><Text style={styles.muted}>Create your first recruiting list above.</Text></View> : <><ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.listTabs}>{lists.map((list) => <Pressable key={list.id} onPress={() => setSelectedId(list.id)} style={[styles.listTab, selectedId === list.id && { backgroundColor: accent, borderColor: accent }]}><Text style={[styles.listTabText, selectedId === list.id && styles.listTabTextActive]}>{list.name}</Text></Pressable>)}</ScrollView>{selected && <View style={styles.selectedListCard}><View style={styles.selectedListHeading}><View><Text style={styles.selectedListTitle}>{selected.name}</Text><Text style={styles.muted}>{selectedAthletes.length} athlete{selectedAthletes.length === 1 ? '' : 's'}</Text></View><Pressable onPress={deleteList}><Text style={styles.deleteText}>Delete</Text></Pressable></View><View style={styles.listActions}><Pressable onPress={() => setShowAdd((value) => !value)} style={[styles.outlineButton, { borderColor: accent }]}><Text style={[styles.outlineButtonText, { color: accent }]}>{showAdd ? 'Hide athletes' : 'Add athletes'}</Text></Pressable></View>{showAdd && <View style={styles.availableList}>{athletes.map((athlete) => <Pressable key={athlete.id} onPress={() => toggleAthlete(athlete)} style={styles.athleteRow}><View style={styles.personAvatar}>{athlete.avatar_url ? <Image source={{ uri: athlete.avatar_url }} style={styles.personAvatarImage} /> : <Text style={styles.personInitial}>{(athlete.first_name ?? athlete.username ?? 'A').charAt(0)}</Text>}</View><View style={styles.personCopy}><Text style={styles.personName}>{[athlete.first_name, athlete.last_name].filter(Boolean).join(' ') || athlete.username}</Text><Text style={styles.personHandle}>{[athlete.sport, athlete.position].filter(Boolean).join(' Â· ') || 'Athlete profile'}</Text></View><Text style={[styles.checkText, memberIds.has(athlete.id) && { color: accent }]}>{memberIds.has(athlete.id) ? 'Added' : 'Add'}</Text></Pressable>)}</View>}{selectedAthletes.length > 0 && <View style={styles.messageListCard}><Text style={styles.selectedListTitle}>Message everyone</Text><Text style={styles.muted}>Messages are sent individually to mutual connections only.</Text><TextInput value={message} onChangeText={setMessage} placeholder="Write a message to this listâ€¦" placeholderTextColor="#8a98a8" multiline maxLength={2000} style={styles.listMessageInput} /><Pressable onPress={messageEveryone} disabled={!message.trim() || saving} style={[styles.messageEveryoneButton, { backgroundColor: accent }, (!message.trim() || saving) && styles.disabled]}><Send color="#fff" size={16} /><Text style={styles.addListText}>{saving ? 'Sendingâ€¦' : 'Message everyone'}</Text></Pressable></View>}</View>}</>}</ScrollView></SafeAreaView>;
}

function BottomNav({ active, accent, onProfile, onMessages }: { active: 'profile' | 'messages'; accent: string; onProfile: () => void; onMessages: () => void }) {
  return <View style={styles.bottomNav}><Pressable onPress={onProfile} style={[styles.navItem, active === 'profile' && { backgroundColor: `${accent}14` }]}><UserRound color={active === 'profile' ? accent : '#8290a0'} size={19} /><Text style={[styles.navLabel, active === 'profile' && { color: accent }]}>Profile</Text></Pressable><Pressable onPress={onMessages} style={[styles.navItem, active === 'messages' && { backgroundColor: `${accent}14` }]}><MessageCircle color={active === 'messages' ? accent : '#8290a0'} size={19} /><Text style={[styles.navLabel, active === 'messages' && { color: accent }]}>Messages</Text></Pressable></View>;
}

function Messages({ userId, onBack, accent = '#2588d8', initialTargetId }: { userId: string; onBack: () => void; accent?: string; initialTargetId?: string }) {
  const [people, setPeople] = useState<MessagePerson[]>([]); const [selected, setSelectedState] = useState<MessagePerson | null>(null); const [messages, setMessages] = useState<Message[]>([]); const [draft, setDraft] = useState(''); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const setSelected = (person: MessagePerson | null) => { if (person === null) onBack(); else setSelectedState(person); };
  const name = (person: MessagePerson) => [person.first_name, person.last_name].filter(Boolean).join(' ') || person.username || 'CoachPoints member';
  const loadInbox = async () => { setLoading(true); const { data, error: inboxError } = await supabase.rpc('get_direct_message_inbox'); if (inboxError) { setError(inboxError.message); setLoading(false); return; } const ids = (data ?? []).map((row: { friend_id: string }) => row.friend_id); if (!ids.length) { setPeople([]); setLoading(false); return; } const [athletes, coaches] = await Promise.all([supabase.from('public_profile_cards').select('id, username, first_name, last_name, avatar_url').in('id', ids), supabase.from('public_coach_profile_cards').select('id, username, first_name, last_name, avatar_url').in('id', ids)]); setPeople([...(athletes.data ?? []), ...(coaches.data ?? [])] as MessagePerson[]); setError(athletes.error?.message ?? coaches.error?.message ?? ''); setLoading(false); };
  const loadConversation = async (person: MessagePerson) => { setSelected(person); setError(''); const { data, error: messageError } = await supabase.from('direct_messages').select('id, sender_id, recipient_id, body, created_at, read_at').or(`and(sender_id.eq.${userId},recipient_id.eq.${person.id}),and(sender_id.eq.${person.id},recipient_id.eq.${userId})`).order('created_at', { ascending: true }).limit(250); if (messageError) { setError(messageError.message); return; } setMessages((data ?? []) as Message[]); await supabase.from('direct_messages').update({ read_at: new Date().toISOString() }).eq('sender_id', person.id).eq('recipient_id', userId).is('read_at', null); };
  useEffect(() => { void loadInbox(); const channel = supabase.channel(`passport-messages-${userId}`).on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'direct_messages', filter: `recipient_id=eq.${userId}` }, (payload) => { const message = payload.new as Message; if (selected?.id === message.sender_id) { setMessages((current) => [...current, message]); void supabase.from('direct_messages').update({ read_at: new Date().toISOString() }).eq('id', message.id); } else void loadInbox(); }).subscribe(); return () => { void supabase.removeChannel(channel); }; }, [userId, selected?.id]);
  useEffect(() => { if (!initialTargetId || selected?.id === initialTargetId) return; const target = people.find((person) => person.id === initialTargetId); if (target) { void loadConversation(target); return; } let cancelled = false; void (async () => { const [athlete, coach] = await Promise.all([supabase.from('public_profile_cards').select('id, username, first_name, last_name, avatar_url').eq('id', initialTargetId).maybeSingle(), supabase.from('public_coach_profile_cards').select('id, username, first_name, last_name, avatar_url').eq('id', initialTargetId).maybeSingle()]); const profile = athlete.data ?? coach.data; if (!cancelled && profile) void loadConversation(profile as MessagePerson); })(); return () => { cancelled = true; }; }, [initialTargetId, people, selected?.id]);
  const send = async () => { if (!selected || !draft.trim() || busy) return; setBusy(true); setError(''); const { data, error: sendError } = await supabase.from('direct_messages').insert({ sender_id: userId, recipient_id: selected.id, body: draft.trim() }).select('id, sender_id, recipient_id, body, created_at, read_at').single(); if (sendError) setError(sendError.message.includes('row-level security') ? 'Messaging is available only with mutual connections.' : sendError.message); else { setMessages((current) => [...current, data as Message]); setDraft(''); void loadInbox(); } setBusy(false); };
  return <SafeAreaView style={styles.safe}><StatusBar style="dark" /><View style={styles.messageTopbar}><Pressable onPress={selected ? () => { setSelected(null); setMessages([]); setError(''); } : onBack} style={styles.backButton}><ArrowLeft color={accent} size={20} /></Pressable><View style={styles.messageTopTitle}><Text style={[styles.topbarKicker, { color: accent }]}>COACHPOINTS</Text><Text style={styles.topbarTitle}>{selected ? name(selected) : 'Messages'}</Text></View>{selected ? <Pressable onPress={onBack} style={[styles.messageOnline, { backgroundColor: `${accent}14` }]}><UserRound color={accent} size={18} /></Pressable> : <View />}</View>{selected ? <KeyboardAvoidingView style={styles.conversation} behavior={Platform.OS === 'ios' ? 'padding' : undefined}><ScrollView contentContainerStyle={styles.messageList} keyboardShouldPersistTaps="handled">{messages.length ? messages.map((message) => <View key={message.id} style={[styles.messageBubble, message.sender_id === userId ? [styles.myMessage, { backgroundColor: accent }] : styles.theirMessage]}><Text style={[styles.messageBody, message.sender_id === userId && styles.myMessageBody]}>{message.body}</Text><Text style={[styles.messageTime, message.sender_id === userId && styles.myMessageTime]}>{formatMessageTime(message.created_at)}</Text></View>) : <View style={styles.messageEmpty}><MessageCircle color={accent} size={30} /><Text style={styles.messageEmptyTitle}>Start the conversation</Text><Text style={styles.muted}>Send a message to {name(selected)}.</Text></View>}{error ? <Text style={styles.messageError}>{error}</Text> : null}</ScrollView><View style={styles.composer}><TextInput value={draft} onChangeText={setDraft} placeholder="Write a messageâ€¦" placeholderTextColor="#8a98a8" multiline maxLength={2000} style={styles.composerInput} onSubmitEditing={send} /><Pressable onPress={send} disabled={!draft.trim() || busy} style={[styles.sendButton, { backgroundColor: accent }, (!draft.trim() || busy) && styles.disabled]}><Send color="#fff" size={17} /></Pressable></View></KeyboardAvoidingView> : <ScrollView contentContainerStyle={styles.inboxList} refreshControl={<RefreshControl refreshing={loading} onRefresh={loadInbox} tintColor={accent} />}>{error ? <Text style={styles.messageError}>{error}</Text> : null}{!loading && !people.length ? <View style={styles.messageEmpty}><MessageCircle color={accent} size={32} /><Text style={styles.messageEmptyTitle}>No conversations yet</Text><Text style={styles.muted}>Connect with someone on CoachPoints to start messaging.</Text></View> : people.map((person) => <Pressable key={person.id} onPress={() => loadConversation(person)} style={styles.personRow}><View style={styles.personAvatar}>{person.avatar_url ? <Image source={{ uri: person.avatar_url }} style={styles.personAvatarImage} /> : <Text style={[styles.personInitial, { color: accent }]}>{name(person).charAt(0)}</Text>}</View><View style={styles.personCopy}><Text style={styles.personName}>{name(person)}</Text><Text style={[styles.personHandle, { color: `${accent}99` }]}>{person.username ? `@${person.username}` : 'CoachPoints connection'}</Text></View><ChevronRight color="#9aa8b6" size={18} /></Pressable>)}</ScrollView>}</SafeAreaView>;
}

function formatMessageTime(value: string) { return new Date(value).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }); }
function Detail({ accent, icon, label, value }: { accent?: string; icon: React.ReactNode; label: string; value?: string | null }) { return <View style={styles.detail}><View style={[styles.detailIcon, accent && { backgroundColor: `${accent}18` }]}>{icon}</View><View style={styles.detailText}><Text style={styles.detailLabel}>{label}</Text><Text style={styles.detailValue}>{value || 'Not added yet'}</Text></View></View>; }
function ContactLine({ icon, text }: { icon: React.ReactNode; text: string }) { return <View style={styles.contactLine}>{icon}<Text style={styles.contactText}>{text}</Text></View>; }
function EmptyState({ message, onRetry }: { message: string; onRetry: () => void }) { return <View style={styles.empty}><Text style={styles.sectionTitle}>Profile unavailable</Text><Text style={styles.muted}>{message}</Text><Pressable onPress={onRetry} style={styles.primaryButton}><Text style={styles.primaryButtonText}>Try again</Text></Pressable></View>; }
function formatObject(value?: Record<string, string> | null) { if (!value) return null; return Object.entries(value).slice(0, 2).map(([key, item]) => `${key}: ${item}`).join(' Â· '); }

